const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;padding:10px;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;font-size:13px;line-height:1.35;display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden}\n.card[data-size=\"3x3\"],.card[data-size=\"6x3\"]{padding:8px}\n.card *{box-sizing:border-box}\nbutton{font:inherit;color:var(--ink);cursor:pointer;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));border-radius:10px;padding:0 10px;min-height:34px;display:inline-flex;align-items:center;justify-content:center;white-space:nowrap;margin:0}\nbutton:disabled{opacity:.35;cursor:default}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.danger{border-color:#B4533A;box-shadow:inset 0 0 0 1px #B4533A;font-weight:700}\n.main,.screen{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto}\n.head{flex:none;display:flex;align-items:center;gap:4px}\n.nav{width:30px;min-height:30px;padding:0;font-size:18px;line-height:1}\n.mlabel{flex:1;min-width:0;min-height:30px;font-weight:700;font-size:14px;border-color:transparent;background:transparent;padding:0 4px}\n.hero{flex:none;display:flex;flex-direction:column;gap:2px;min-width:0}\n.hl{font-size:12px;color:var(--muted);font-weight:600}\n.hv{font-size:30px;font-weight:700;line-height:1.1;font-variant-numeric:tabular-nums;white-space:nowrap}\n.card[data-size=\"3x3\"] .hv{font-size:28px}\n.card[data-size=\"6x3\"] .hv{font-size:26px}\n.card[data-size=\"6x6\"] .hv{font-size:36px}\n.card[data-size] .hv.xl{font-size:22px}\n.track{height:8px;border-radius:99px;background:var(--soft);overflow:hidden;margin:5px 0 3px}\n.fill{display:block;height:100%;background:var(--accent);border-radius:99px}\n.over .fill{background:#B4533A}\n.sub{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:0 8px;font-size:12px;color:var(--muted)}\n.spent{white-space:nowrap}\n.bud{border:0;background:transparent;min-height:24px;padding:0 2px;color:var(--ink);font-size:12px;text-decoration:underline;text-underline-offset:2px}\n.hint{font-size:11px;color:var(--muted)}\n.row3{flex:none;display:flex;gap:6px}\n.row3 button{flex:1;min-width:0;padding:0 4px}\n.row3 .add{flex:1.6}\n.add{min-height:36px}\n.s63{flex-direction:row;gap:12px}\n.s63 .left{flex:0 0 152px;min-width:0;display:flex;flex-direction:column;gap:6px;justify-content:space-between}\n.s63 .right{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px}\n.s63 .add{min-height:32px}\n.herorow{flex:none;display:flex;align-items:flex-end;gap:12px}\n.herorow .hero{flex:1}\n.herorow .add{flex:0 0 108px;min-height:40px}\n.cols{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:10px}\n.tabs{flex:none;display:flex;gap:4px}\n.tab{flex:1;min-height:30px;font-size:12px;padding:0 6px}\n.tab.on{background:var(--soft);border-color:var(--accent);font-weight:700}\n.pane{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;background:var(--panel-paper);border:1px solid var(--line);border-radius:12px;overflow:hidden}\n.ph{flex:none;padding:6px 10px 0;font-size:12px}\n.pt{font-weight:700}\n.cats,.ents{padding:2px 10px 8px;display:flex;flex-direction:column}\n.tot{display:flex;justify-content:space-between;gap:8px;font-size:12px;color:var(--muted);padding:5px 0}\n.tot b{color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}\n.crow{padding:5px 0;border-top:1px solid var(--line)}\n.ctop{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;align-items:baseline}\n.cname{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.cpct{font-size:11px;color:var(--muted)}\n.camt{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}\n.cbar{height:5px;border-radius:9px;background:var(--soft);margin-top:3px;overflow:hidden}\n.cbar i{display:block;height:100%;background:var(--accent);border-radius:9px}\n.lrow{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:8px;align-items:center;justify-content:stretch;width:100%;min-height:40px;padding:4px 0;border:0;border-top:1px solid var(--line);border-radius:0;background:transparent;text-align:left}\n.ld{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}\n.lm{display:flex;flex-direction:column;min-width:0}\n.lc{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.ln{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.la{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}\n.empty{padding:16px 10px;color:var(--muted);font-size:12px;text-align:center}\n.sh{flex:none;display:flex;align-items:center;gap:6px}\n.back{width:30px;min-height:30px;padding:0;font-size:18px;line-height:1}\n.st{font-weight:700;font-size:14px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.sbody{padding:2px 1px}\n.sf{flex:none;display:flex;flex-direction:column;gap:5px}\n.btns{display:flex;gap:6px}\n.btns button{flex:1;min-width:0;padding:0 6px}\n.err{font-size:12px;font-weight:600}\n.fld{display:flex;flex-direction:column;gap:4px;margin-bottom:9px}\n.fl{font-size:12px;color:var(--muted)}\n.inp{width:100%;min-width:0;min-height:34px;padding:4px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit}\n.inp.amt{font-size:18px;font-weight:700}\n.chips{display:flex;flex-wrap:wrap;gap:5px}\n.chip{min-height:30px;padding:0 10px;border-radius:99px;font-size:12px}\n.chip.on{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.tip{font-size:12px;color:var(--muted)}\n.mlist{display:flex;flex-direction:column;gap:5px;padding-bottom:4px}\n.mrow{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:0 8px;justify-content:stretch;align-items:center;width:100%;min-height:46px;padding:5px 9px;text-align:left;white-space:normal}\n.mrow.cur{border-color:var(--accent);background:var(--soft)}\n.mm{font-weight:700;white-space:nowrap}\n.ms{font-weight:700;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}\n.md{grid-column:1/-1;font-size:11px;color:var(--muted)}\n";
const PRESETS=['餐饮','交通','日用','居住','娱乐','医疗','其他'];
const DEFAULT_BUDGET=3000;
function pad(n){return n<10?'0'+n:''+n}
function todayStr(){const d=new Date();return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function curMonth(){return todayStr().slice(0,7)}
function r2(n){return Math.round(n*100)/100}
function money(n){
  n=r2(n);const neg=n<0;n=Math.abs(n);
  const p=n.toFixed(2).split('.');
  let f=p[1];
  if(f==='00')f='';else if(f.charAt(1)==='0')f=f.charAt(0);
  return (neg?'-':'')+p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',')+(f?'.'+f:'');
}
function monthLabel(m){return m.slice(0,4)+'年'+Number(m.slice(5,7))+'月'}
function shiftMonth(m,d){
  let y=Number(m.slice(0,4));let mo=Number(m.slice(5,7))-1+d;
  y+=Math.floor(mo/12);mo=((mo%12)+12)%12;
  return y+'-'+pad(mo+1);
}
function daysIn(m){return new Date(Number(m.slice(0,4)),Number(m.slice(5,7)),0).getDate()}
function ensure(s){
  s=s&&typeof s==='object'?s:{};
  const entries=Array.isArray(s.entries)?s.entries:[];
  const budgets=Array.isArray(s.budgets)&&s.budgets.length?s.budgets:[{month:curMonth(),amount:DEFAULT_BUDGET}];
  return Object.assign({},s,{entries:entries,budgets:budgets});
}
function initialize(s){
  if(s&&Array.isArray(s.entries)&&Array.isArray(s.budgets)&&s.budgets.length)return s;
  return ensure(s);
}
function budgetFor(s,m){
  let best=null;let first=null;
  s.budgets.forEach(b=>{
    if(!first||b.month<first.month)first=b;
    if(b.month<=m&&(!best||b.month>best.month))best=b;
  });
  const hit=best||first;
  return hit?Number(hit.amount)||DEFAULT_BUDGET:DEFAULT_BUDGET;
}
function summarize(s,m){
  const list=s.entries.filter(e=>typeof e.date==='string'&&e.date.slice(0,7)===m);
  list.sort((a,b)=>a.date<b.date?1:(a.date>b.date?-1:(b.at||0)-(a.at||0)));
  const sums={};let total=0;
  list.forEach(e=>{const a=Number(e.amount)||0;sums[e.cat]=(sums[e.cat]||0)+a;total+=a;});
  const rows=Object.keys(sums).map(k=>({name:k,amount:r2(sums[k])}));
  rows.sort((a,b)=>b.amount-a.amount);
  total=r2(total);
  const budget=budgetFor(s,m);
  return {list:list,rows:rows,total:total,budget:budget,left:r2(budget-total)};
}
function minMonth(s){
  let m=curMonth();
  s.entries.forEach(e=>{const k=String(e.date).slice(0,7);if(k.length===7&&k<m)m=k;});
  return m;
}
function setBudget(s,m,amount){
  const cur=curMonth();
  let b=s.budgets.map(x=>({month:x.month,amount:x.amount}));
  if(m<cur){
    const nm=shiftMonth(m,1);
    if(!b.some(x=>x.month===nm))b.push({month:nm,amount:budgetFor(s,nm)});
  }
  b=b.filter(x=>x.month!==m);
  b.push({month:m,amount:amount});
  b.sort((x,y)=>x.month<y.month?-1:(x.month>y.month?1:0));
  return Object.assign({},s,{budgets:b});
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,size,uid}=ctx;
  const S=ensure(state);
  const cur=curMonth();
  if(!ui.month||ui.month>cur)ui.month=cur;
  const M=ui.month;
  const minM=minMonth(S);
  const sum=summarize(S,M);
  if(!ui.tab)ui.tab='cats';
  let view=ui.view||'main';
  if((view==='cats'||view==='list')&&size!=='3x3')view='main';
  const yen=n=>'¥'+money(n);

  function go(v,extra){Object.assign(ui,extra||{});ui.view=v;redraw();}
  function nextUi(over){
    return Object.assign({month:ui.month,tab:ui.tab,view:ui.ret||'main',ret:null,draft:null,editId:null,err:'',confirmDel:false,saving:false},over||{});
  }
  function failSave(){ui.saving=false;ui.err='保存失败，请重试';redraw();}
  function after(p){return p.then(ok=>{if(ok===false)failSave();}).catch(failSave);}
  function openAdd(){
    const d=M===cur?todayStr():M+'-'+pad(daysIn(M));
    ui.ret=view==='list'?'list':null;
    go('form',{draft:{amount:'',cat:'',custom:'',date:d,note:''},editId:null,err:'',confirmDel:false,saving:false});
  }
  function openEdit(e){
    ui.ret=view==='list'?'list':null;
    go('form',{draft:{amount:String(e.amount),cat:e.cat,custom:'',date:e.date,note:e.note||''},editId:e.id,err:'',confirmDel:false,saving:false});
  }
  function openBudget(){
    ui.ret=null;
    go('budget',{draft:{budget:String(sum.budget)},err:'',saving:false});
  }
  function closeForm(){
    const r=ui.ret||'main';
    go(r,{draft:null,editId:null,err:'',confirmDel:false,saving:false,ret:null});
  }
  function fail(msg){ui.err=msg;redraw();}

  function saveEntry(){
    if(ui.saving)return;
    const d=ui.draft;if(!d)return;
    const raw=String(d.amount).trim();
    const amt=Number(raw);
    const cat=(d.custom||'').trim()||d.cat;
    if(raw===''||!isFinite(amt)||amt<=0)return fail('请输入大于 0 的金额');
    if(amt>=1e9)return fail('金额太大了，请检查');
    if(!cat)return fail('请选择或输入类别');
    if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date||''))return fail('请选择日期');
    if(d.date>todayStr())return fail('日期不能晚于今天');
    const rec={amount:r2(amt),cat:cat,date:d.date,note:(d.note||'').trim()};
    const id=ui.editId;
    const newId=id?null:uid();
    const at=Date.now();
    ui.saving=true;
    after(commit(s=>{
      s=ensure(s);
      const entries=id
        ?s.entries.map(e=>e.id===id?Object.assign({},e,rec):e)
        :s.entries.concat([Object.assign({id:newId,at:at},rec)]);
      return Object.assign({},s,{entries:entries});
    },nextUi({month:rec.date.slice(0,7)})));
  }
  function deleteEntry(){
    if(ui.saving)return;
    const id=ui.editId;
    ui.saving=true;
    after(commit(s=>{
      s=ensure(s);
      return Object.assign({},s,{entries:s.entries.filter(e=>e.id!==id)});
    },nextUi()));
  }
  function saveBudget(){
    if(ui.saving)return;
    const d=ui.draft;if(!d)return;
    const raw=String(d.budget).trim();
    const amt=Number(raw);
    if(raw===''||!isFinite(amt)||amt<=0)return fail('请输入大于 0 的预算金额');
    if(amt>=1e9)return fail('预算太大了，请检查');
    ui.saving=true;
    after(commit(s=>setBudget(ensure(s),M,r2(amt)),nextUi({view:'main',ret:null})));
  }


  function navBtn(txt,label,dis,fn){
    return el('button',{class:'nav',type:'button','aria-label':label,disabled:dis,onclick:fn},txt);
  }
  function header(){
    return el('div',{class:'head'},
      navBtn('‹','上一个月',!(M>minM),()=>{ui.month=shiftMonth(M,-1);redraw();}),
      el('button',{class:'mlabel',type:'button','aria-label':'查看各月汇总',onclick:()=>go('months')},monthLabel(M)),
      navBtn('›','下一个月',!(M<cur),()=>{ui.month=shiftMonth(M,1);redraw();}));
  }
  function hero(){
    const over=sum.left<0;
    const mm=Number(M.slice(5,7))+'月';
    const label=over?(M===cur?'⚠ 本月已超支':'⚠ '+mm+'已超支'):(M===cur?'本月还剩':mm+'结余');
    const txt=yen(Math.abs(sum.left));
    const p=sum.budget>0?Math.min(100,Math.max(0,sum.total/sum.budget*100)):100;
    const fill=el('i',{class:'fill'});
    fill.style.width=(over?100:p)+'%';
    const track=el('div',{class:'track',role:'progressbar','aria-label':'预算已使用 '+Math.round(p)+'%','aria-valuemin':'0','aria-valuemax':'100','aria-valuenow':String(Math.round(p))},fill);
    const parts=[
      el('div',{class:'hl'},label),
      el('div',{class:'hv'+(txt.length>9?' xl':'')},txt),
      track,
      el('div',{class:'sub'},
        el('span',{class:'spent'},'已花 '+yen(sum.total)),
        el('button',{class:'bud',type:'button','aria-label':'修改月预算，当前 '+yen(sum.budget),onclick:openBudget},'预算 '+yen(sum.budget)+' ✎'))
    ];
    if(size!=='3x3'&&M===cur&&sum.left>0){
      const dl=daysIn(M)-Number(todayStr().slice(8,10))+1;
      parts.push(el('div',{class:'hint'},'还剩 '+dl+' 天，日均可花 '+yen(sum.left/dl)));
    }
    return el('div',{class:'hero'+(over?' over':'')},...parts);
  }
  function emptyNote(){
    return el('div',{class:'empty'},M===cur?'本月还没有账目，点「记一笔」开始。':'这个月没有账目。');
  }
  function catList(){
    if(!sum.rows.length)return emptyNote();
    const rows=sum.rows.map(r=>{
      const p=sum.total>0?r.amount/sum.total*100:0;
      const bar=el('i',{});
      bar.style.width=Math.max(2,p)+'%';
      return el('div',{class:'crow'},
        el('div',{class:'ctop'},
          el('span',{class:'cname'},r.name),
          el('span',{class:'cpct'},Math.round(p)+'%'),
          el('span',{class:'camt'},yen(r.amount))),
        el('div',{class:'cbar'},bar));
    });
    return el('div',{class:'cats'},
      el('div',{class:'tot'},el('span',{},'支出合计'),el('b',{},yen(sum.total))),
      ...rows);
  }
  function entryList(){
    if(!sum.list.length)return emptyNote();
    const rows=sum.list.map(e=>el('button',{class:'lrow',type:'button','aria-label':'修改 '+e.date+' '+e.cat+' '+yen(e.amount),onclick:()=>openEdit(e)},
      el('span',{class:'ld'},e.date.slice(5)),
      el('span',{class:'lm'},el('b',{class:'lc'},e.cat),el('span',{class:'ln'},e.note||'')),
      el('span',{class:'la'},yen(e.amount))));
    return el('div',{class:'ents'},
      el('div',{class:'tot'},el('span',{},'共 '+sum.list.length+' 笔'),el('span',{},'点一笔可修改')),
      ...rows);
  }
  function pane(title,body,withHead){
    const kids=[];
    if(withHead)kids.push(el('div',{class:'ph'},el('span',{class:'pt'},title)));
    kids.push(el('div',{class:'scroll'},body));
    return el('div',{class:'pane'},...kids);
  }
  function tabBtn(t,k){
    return el('button',{class:'tab'+(ui.tab===k?' on':''),type:'button','aria-pressed':String(ui.tab===k),onclick:()=>{ui.tab=k;redraw();}},t);
  }
  function tabs(){return el('div',{class:'tabs'},tabBtn('分类','cats'),tabBtn('明细','list'));}
  function addBtn(){
    return el('button',{class:'btn primary add',type:'button',onclick:openAdd},M===cur?'＋ 记一笔':'＋ 补记一笔');
  }
  function screen(title,body,footer,onBack){
    const head=[];
    if(onBack)head.push(el('button',{class:'back',type:'button','aria-label':'返回',onclick:onBack},'‹'));
    head.push(el('span',{class:'st'},title));
    const kids=[el('div',{class:'sh'},...head),el('div',{class:'scroll sbody'},body)];
    if(footer)kids.push(el('div',{class:'sf'},...footer));
    return el('div',{class:'screen'},...kids);
  }
  function renderMain(){
    if(size==='3x3'){
      return el('div',{class:'main s33'},header(),hero(),
        el('div',{class:'row3'},addBtn(),
          el('button',{type:'button',onclick:()=>go('cats')},'分类'),
          el('button',{type:'button',onclick:()=>go('list')},'明细')));
    }
    if(size==='6x3'){
      return el('div',{class:'main s63'},
        el('div',{class:'left'},header(),hero(),addBtn()),
        el('div',{class:'right'},tabs(),pane('',ui.tab==='list'?entryList():catList(),false)));
    }
    if(size==='3x6'){
      return el('div',{class:'main s36'},header(),hero(),addBtn(),tabs(),pane('',ui.tab==='list'?entryList():catList(),false));
    }
    return el('div',{class:'main s66'},header(),
      el('div',{class:'herorow'},hero(),addBtn()),
      el('div',{class:'cols'},pane('分类支出',catList(),true),pane('明细',entryList(),true)));
  }


  function field(label,node){return el('label',{class:'fld'},el('span',{class:'fl'},label),node);}
  function errLine(){return ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;}
  function footerWith(btns){
    const f=[];
    const e=errLine();
    if(e)f.push(e);
    f.push(el('div',{class:'btns'},...btns));
    return f;
  }
  function renderForm(){
    const d=ui.draft||(ui.draft={amount:'',cat:'',custom:'',date:todayStr(),note:''});
    const editing=!!ui.editId;
    const enter=e=>{if(e.key==='Enter')saveEntry();};
    const opts=PRESETS.slice();
    S.entries.forEach(e=>{if(e.cat&&opts.indexOf(e.cat)<0)opts.push(e.cat);});
    if(d.cat&&opts.indexOf(d.cat)<0)opts.push(d.cat);
    const chipEls=[];
    const chips=opts.map(c=>{
      const on=c===d.cat&&!(d.custom||'').trim();
      const b=el('button',{class:'chip'+(on?' on':''),type:'button','aria-pressed':String(on),onclick:()=>{d.cat=c;d.custom='';ui.err='';redraw();}},c);
      chipEls.push([b,c]);
      return b;
    });
    const amount=el('input',{class:'inp amt',type:'number',inputmode:'decimal',step:'any',min:'0',placeholder:'0.00','aria-label':'金额（元）',value:d.amount,oninput:e=>{d.amount=e.target.value;},onkeydown:enter});
